 	}

 	if strings.Contains(realPath, "/mise/installs/") {
-		return "mise upgrade entire"
+		return updateHint{Command: "mise upgrade entire"}
+	}
+
+	return updateHint{Command: "curl -fsSL https://entire.io/install.sh | bash"}
