46	// MaybeAutoUpdate offers or runs an auto-update after a newer release is
47	// detected. The caller has already printed the standard "version available"
48	// notification. This function is silent on every error path — failures must
49	// never interrupt the CLI.
50	func MaybeAutoUpdate(ctx context.Context, w io.Writer, currentVersion string, release *GitHubRelease) {
51		if release == nil {
52			return
53		}
54		if os.Getenv(envKillSwitch) != "" {
55			logging.Debug(ctx, "auto-update: skipped by kill-switch env")
56			return
57		}
58		if os.Getenv("CI") != "" {
