60			return
61		}
62	
63		g, err := loadGlobal()
64		if err != nil {
65			logging.Debug(ctx, "auto-update: load global settings failed", "error", err.Error())
66			return
67		}
68		mode := g.GetAutoUpdate()
69		if mode == settings.AutoUpdateOff {
70			return
71		}
72	
73		if !stdoutIsTerminal() {
74			logging.Debug(ctx, "auto-update: skipped (no TTY)")
75			return
76		}
77	
78		cmdStr, fromProvenance := resolveUpdateCommand()
79	
80		if mode == settings.AutoUpdateAuto {
81			if !fromProvenance {
82				logging.Debug(ctx, "auto-update: skipped (no install provenance)")
83				return
84			}
85			if !release.PublishedAt.IsZero() && nowFunc().Sub(release.PublishedAt) < autoUpdateSoakDuration {
86				logging.Debug(ctx, "auto-update: skipped (release under soak delay)")
87				return
88			}
89			if cache, cerr := loadCache(); cerr == nil {
90				if !cache.LastUpdateAttemptTime.IsZero() && !cache.LastUpdateAttemptOk &&
91					nowFunc().Sub(cache.LastUpdateAttemptTime) < autoUpdateRetryCooldown {
92					logging.Debug(ctx, "auto-update: skipped (recent failure)")
93					return
94				}
95			}
96		}
97	
98		if mode == settings.AutoUpdatePrompt {
99			confirmed, perr := confirmUpdate(release.TagName)
100			if perr != nil {
