120	// confirmUpdate prompts the user interactively. Returns false if they declined
121	// or aborted (Ctrl-C / timeout), true only on explicit yes.
122	func confirmUpdate(latest string) (bool, error) {
123		var confirmed bool
124		form := huh.NewForm(
125			huh.NewGroup(
126				huh.NewConfirm().
127					Title(fmt.Sprintf("Install Entire CLI %s now?", latest)).
128					Affirmative("Yes").
129					Negative("No").
130					Value(&confirmed),
131			),
132		).WithTheme(huh.ThemeDracula())
133		if os.Getenv("ACCESSIBLE") != "" {
134			form = form.WithAccessible(true)
135		}
136		if err := form.Run(); err != nil {
137			if errors.Is(err, huh.ErrUserAborted) || errors.Is(err, huh.ErrTimeout) {
138				return false, nil
139			}
140			return false, fmt.Errorf("confirm form: %w", err)
141		}
142		return confirmed, nil
143	}
