145	// realRunInstaller shells out to the installer command, streaming stdin/stdout/stderr
146	// so password prompts and progress output reach the user.
147	func realRunInstaller(ctx context.Context, cmdStr string) error {
148		var c *exec.Cmd
149		if runtime.GOOS == "windows" {
150			c = exec.CommandContext(ctx, "cmd", "/C", cmdStr)
151		} else {
152			c = exec.CommandContext(ctx, "sh", "-c", cmdStr)
153		}
154		c.Stdin = os.Stdin
155		c.Stdout = os.Stdout
156		c.Stderr = os.Stderr
157		if err := c.Run(); err != nil {
158			return fmt.Errorf("installer exited: %w", err)
159		}
160		return nil
161	}
162	
163	// recordUpdateAttempt persists the outcome of the last install attempt so
164	// "auto" mode can back off after failures.
165	func recordUpdateAttempt(ctx context.Context, ok bool) {
166		cache, err := loadCache()
167		if err != nil {
168			cache = &VersionCache{}
169		}
170		cache.LastUpdateAttemptTime = nowFunc()
171		cache.LastUpdateAttemptOk = ok
172		if err := saveCache(cache); err != nil {
173			logging.Debug(ctx, "auto-update: save cache failed", "error", err.Error())
174		}
175	}
