177	// RunUpdateNow is the one-shot update entry point used by `entire update`.
178	// It ignores the 24h check cache and the auto_update mode gate, but still
179	// respects the kill-switch env, TTY/CI checks (unless skipPrompt is true),
180	// and resolves the installer command from provenance.
181	// Returns (ran bool, err error). ran=false means the user declined or
182	// the gates blocked execution; err indicates a real failure.
183	func RunUpdateNow(ctx context.Context, w io.Writer, checkOnly, skipPrompt bool) (bool, error) {
184		if os.Getenv(envKillSwitch) != "" {
185			return false, errors.New("auto-update disabled by " + envKillSwitch)
186		}
187	
188		cmdStr, fromProvenance := resolveUpdateCommand()
189		if checkOnly {
190			if fromProvenance {
191				fmt.Fprintf(w, "Update command (from install provenance): %s\n", cmdStr)
192			} else {
193				fmt.Fprintf(w, "Update command (inferred from executable path): %s\n", cmdStr)
194			}
195			return false, nil
196		}
197	
198		if !skipPrompt {
199			if !stdoutIsTerminal() {
200				return false, errors.New("refusing to run installer on non-TTY stdout (use --yes)")
201			}
202			confirmed, perr := confirmUpdate("")
203			if perr != nil {
204				return false, fmt.Errorf("prompt: %w", perr)
205			}
206			if !confirmed {
207				return false, nil
208			}
209		}
210	
211		fmt.Fprintf(w, "\nUpdating Entire CLI: %s\n", cmdStr)
212		runErr := runInstaller(ctx, cmdStr)
213		recordUpdateAttempt(ctx, runErr == nil)
214		if runErr != nil {
215			return false, fmt.Errorf("installer: %w", runErr)
216		}
217		fmt.Fprintf(w, "Update complete. Re-run entire to use the new version.\n")
218		return true, nil
219	}

