29	// CheckAndNotify performs a version check and notifies the user if a newer version is available.
30	// This is the main entry point for the version check system.
31	// The function is silent on all errors to avoid interrupting CLI operations.
32	func CheckAndNotify(ctx context.Context, w io.Writer, currentVersion string) {
33		// Skip checks for dev builds
34		if currentVersion == "dev" || currentVersion == "" {
35			return
36		}
37	
38		// Ensure the global config directory exists
39		if err := ensureGlobalConfigDir(); err != nil {
40			// Silent failure - don't block CLI operations
41			return
42		}
43	
44		// Load the cache to check when we last fetched
45		cache, err := loadCache()
46		if err != nil {
47			cache = &VersionCache{}
48		}
49	
50		// Skip if we checked recently (within 24 hours)
51		if time.Since(cache.LastCheckTime) < checkInterval {
52			return
53		}
54	
55		// Fetch the latest release from the appropriate channel
56		var release *GitHubRelease
57		if isNightly(currentVersion) {
58			release, err = fetchLatestNightlyRelease(ctx)
59		} else {
60			release, err = fetchLatestRelease(ctx)
61		}
62	
63		// Always update cache to avoid retrying on every CLI invocation
64		cache.LastCheckTime = time.Now()
65		if saveErr := saveCache(cache); saveErr != nil {
66			logging.Debug(ctx, "version check: failed to save cache",
67				"error", saveErr.Error())
68		}
69	
70		if err != nil {
71			logging.Debug(ctx, "version check: failed to fetch latest version",
72				"error", err.Error())
73			return
74		}
75	
76		// Show notification and (if configured) offer/run an auto-update when outdated
77		if isOutdated(currentVersion, release.TagName) {
78			printNotification(w, currentVersion, release.TagName)
79			MaybeAutoUpdate(ctx, w, currentVersion, release)
80		}
81	}
