func printNotification(w io.Writer, current, latest string) {
	msg := fmt.Sprintf("\nA newer version of Entire CLI is available: %s (current: %s)\nRun '%s' to update.\n",
		latest, current, updateCommand(current))
	fmt.Fprint(w, msg)
}

